// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint128 prevBalance, uint128 sentAmount, address randomUser) public {
        vm.assume(randomUser != address(0) && randomUser != address(c));
        vm.deal(randomUser, uint256(prevBalance) + uint256(sentAmount));
        vm.prank(randomUser);
        c.addToBalance{value: prevBalance}();
        uint256 balanceBefore = c.getBalance(randomUser);
        vm.prank(randomUser);
        c.addToBalance{value: sentAmount}();
        uint256 balanceAfter = c.getBalance(randomUser);
        assertTrue(balanceAfter == balanceBefore + sentAmount);
    }
}
